export function filterPrayers(entries,query='',category='',favorites=null,intention=''){const norm=x=>String(x).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return entries.filter(p=>(!category||p.category===category)&&(!favorites||favorites.includes(p.id))&&(!intention||(p.intentions||[]).includes(intention))&&norm([p.title,p.latinTitle,p.category,...(p.intentions||[]),...p.sections.map(s=>s.pt+' '+s.la)].join(' ')).includes(norm(query)));}
export function speechChunks(sections,lang,max=220){const output=[];sections.forEach((s,section)=>{const text=s[lang];if(!text)return;const words=text.replace(/(?:^|\n)\s*[V℣]\./g,' ').replace(/(?:^|\n)\s*[R℟]\./g,' ').trim().split(/\s+/).filter(Boolean);let part='';for(const word of words){if(part.length+word.length+1>max&&part){output.push({text:part,section});part='';}part+=(part?' ':'')+word;}if(part)output.push({text:part,section});});return output;}
export function selectVoice(voices,lang,uri=''){if(uri)return voices.find(v=>v.voiceURI===uri)||null;const prefix=lang==='la'?'la':'pt';return voices.find(v=>v.lang.toLowerCase().startsWith(prefix)&&v.localService)||voices.find(v=>v.lang.toLowerCase().startsWith(prefix))||null;}
export class PrayerPlayer{
 constructor({synth,Utterance,onChange=()=>{},onError=()=>{}}){this.synth=synth;this.Utterance=Utterance;this.onChange=onChange;this.onError=onError;this.queue=[];this.index=0;this.state='stopped';this.generation=0;this.timer=null;}
 emit(){this.onChange({state:this.state,index:this.index,total:this.queue.length,section:this.queue[this.index]?.section??-1});}
 configure({sections,lang,voice=null,rate=.85,gap=2}){this.stop();this.queue=speechChunks(sections,lang);this.lang=lang==='la'?'la':'pt-BR';this.voice=voice;this.rate=rate;this.gap=gap;this.emit();}
 play(){if(!this.queue.length)return;if(this.index>=this.queue.length)this.index=0;this.state='playing';this.speak();}
 speak(){clearTimeout(this.timer);if(this.state!=='playing'||!this.queue[this.index])return;const generation=++this.generation;this.synth.cancel();const u=new this.Utterance(this.queue[this.index].text);u.lang=this.voice?.lang||this.lang;if(this.voice)u.voice=this.voice;u.rate=this.rate;this.utterance=u;this.emit();u.onend=()=>{if(generation!==this.generation||this.state!=='playing')return;const previousSection=this.queue[this.index].section;this.index++;if(this.index>=this.queue.length){this.state='finished';this.emit();return;}this.timer=setTimeout(()=>this.speak(),this.queue[this.index].section!==previousSection?this.gap*1000:100);};u.onerror=e=>{if(generation!==this.generation||['canceled','interrupted'].includes(e.error))return;this.state='paused';this.emit();this.onError('A voz não conseguiu reproduzir este trecho. Escolha outra voz ou continue a leitura.');};this.synth.speak(u);}
 pause(){++this.generation;clearTimeout(this.timer);this.synth.cancel();this.state='paused';this.emit();}
 stop(){++this.generation;clearTimeout(this.timer);this.synth.cancel();this.index=0;this.state='stopped';this.emit();}
 step(direction){++this.generation;clearTimeout(this.timer);this.synth.cancel();this.index=Math.max(0,Math.min(this.queue.length-1,this.index+direction));if(this.state==='playing')this.speak();else{this.state='paused';this.emit();}}
}
